def build_agent(sandbox):
    """Optimized structure with dense ballast and lateral containment to prevent cargo loss."""
    deck_top, hull_y = _hull_deck_top(sandbox)
    build_y_min = 2.0
    max_mass = float(sandbox.MAX_STRUCTURE_MASS)
    reference_mass = 59.61
    density_scale = (
        1.0
        if max_mass >= reference_mass - 0.05
        else min(1.0, max(0.35, (max_mass - 0.25) / reference_mass))
    )

    def density(value):
        return float(value) * density_scale

    # Add dense ballast beams at the hull base (y = 2.0 to 2.2)
    for x in (12.5, 13.5, 14.5, 15.5, 16.5, 17.5):
        for y in (2.0, 2.1, 2.2):
            beam = sandbox.add_beam(
                x, y, 0.5, 0.1, density=density(600.0)
            )
            sandbox.set_material_properties(beam, restitution=0.01)
            sandbox.add_joint(beam, None, (x, y), type="rigid")

    # Add horizontal containment beam at y = 2.2 to prevent cargo from moving downward
    containment_beam = sandbox.add_beam(
        15.0, 2.2, 3.0, 0.1, density=density(600.0)
    )
    sandbox.set_material_properties(containment_beam, restitution=0.01)
    sandbox.add_joint(containment_beam, None, (15.0, 2.2), type="rigid")

    # Add rail and lip structures for lateral containment
    for x in (13.5, 16.5):
        rail = sandbox.add_beam(
            x, deck_top + 0.45, 0.2, 0.9, density=density(30.0)
        )
        sandbox.set_material_properties(rail, restitution=0.01)
        sandbox.add_joint(rail, None, (x, deck_top + 0.45), type="rigid")

    for x in (14.5, 15.5):
        lip = sandbox.add_beam(
            x, deck_top + 0.06, 0.18, 0.06, density=density(35.0)
        )
        sandbox.set_material_properties(lip, restitution=0.01)
        sandbox.add_joint(lip, None, (x, deck_top), type="rigid")

    _check_mass(sandbox)
    return containment_beam

